/** Original, deliberately quiet procedural score. No recordings or remote requests. */
let context,master,musicBus,effectsBus,timer,step=0,theme='town';
const town=[60,64,67,72,67,64,62,67,71,74,71,67,57,60,64,69,64,60,55,59,62,67,62,59];
const mystery=[57,null,64,60,null,59,52,null,57,64,null,60];
function tone(midi,time,length,bus,type='sine',gain=.12){if(!context||midi===null)return;const o=context.createOscillator(),g=context.createGain();o.type=type;o.frequency.value=440*2**((midi-69)/12);g.gain.setValueAtTime(0,time);g.gain.linearRampToValueAtTime(gain,time+.04);g.gain.exponentialRampToValueAtTime(.0001,time+length);o.connect(g).connect(bus);o.start(time);o.stop(time+length+.1);}
export function configure(settings,nextTheme='town'){theme=nextTheme;if(!context)return;master.gain.setTargetAtTime(settings.muted?0:1,context.currentTime,.1);musicBus.gain.setTargetAtTime(settings.music*.3,context.currentTime,.1);effectsBus.gain.setTargetAtTime(settings.effects*.45,context.currentTime,.05);}
export function unlock(settings){try{if(!context){context=new (window.AudioContext||window.webkitAudioContext)();master=context.createGain();musicBus=context.createGain();effectsBus=context.createGain();musicBus.connect(master);effectsBus.connect(master);master.connect(context.destination);timer=setInterval(()=>{if(context.state!=='running')return;const notes=theme==='mystery'?mystery:town;const n=notes[step++%notes.length];tone(n,context.currentTime,.8,musicBus,'sine',.15);if(step%4===0)tone((n??57)-12,context.currentTime,1.7,musicBus,'triangle',.06);},450);}void context.resume();configure(settings,theme);}catch{/* Optional audio never blocks play. */}}
export function effect(kind){if(!context)return;const notes=kind==='failure'?[60,56,48]:kind==='success'?[60,64,67,72]:[76];notes.forEach((n,i)=>tone(n,context.currentTime+i*.12,.35,effectsBus,'triangle',.12));}
document.addEventListener('visibilitychange',()=>{if(context){if(document.hidden)void context.suspend();else void context.resume().catch(()=>{});}});
